import { describe, expect, it } from "vitest";
import { checkCommitMessage, checkPullRequest, findAttribution } from "../scripts/commit-rules.mjs";

describe("findAttribution", () => {
  it.each([
    "Co-Authored-By: Claude <noreply@anthropic.com>",
    "co-authored-by: GitHub Copilot <copilot@github.com>",
    "Co-authored-by: Codex <codex@openai.com>",
    "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
    "Generated by ChatGPT",
    "This was generated with Cursor.",
  ])("flags %s", (line) => {
    expect(findAttribution(`feat: add a thing\n\n${line}\n`)).toEqual([line]);
  });

  it.each([
    "Co-authored-by: Aleksandar Manasiev <hello@kheprilab.com>",
    "This PR was generated with [Release Please](https://github.com/googleapis/release-please).",
    "Generated with esbuild.",
    "The judge reviews the snapshot.",
  ])("accepts %s", (line) => {
    expect(findAttribution(`chore: something\n\n${line}\n`)).toEqual([]);
  });
});

describe("checkCommitMessage", () => {
  it.each([
    "feat: add an option",
    "fix(cli): handle an empty task id",
    "refactor!: drop the old config",
    "chore(main): release wepwawet 0.9.0",
    "Merge branch 'main' into feat/x",
    "fixup! feat: add an option",
    "squash! fix: something",
  ])("accepts the subject %s", (subject) => {
    expect(checkCommitMessage(`${subject}\n\nBody.\n`)).toEqual([]);
  });

  it.each([
    "Add an option",
    "feature: add an option",
    "feat(CLI): add an option",
    "feat:missing space",
    "feat: ",
    `feat: ${"x".repeat(101)}`,
  ])("rejects the subject %s", (subject) => {
    expect(checkCommitMessage(`${subject}\n`)).toHaveLength(1);
  });

  it("ignores git comment lines", () => {
    expect(checkCommitMessage("# Please enter the commit message\nfeat: add an option\n")).toEqual([]);
  });

  it("rejects attribution even with a valid subject", () => {
    const errors = checkCommitMessage("feat: add an option\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n");
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain("attribution");
  });
});

describe("checkPullRequest", () => {
  const commit = (sha: string, message: string) => ({ sha, message });

  it("accepts a valid pull request", () => {
    expect(
      checkPullRequest({
        author: "aleksandarlabs",
        body: "## What changed\n\nStuff.",
        commits: [commit("a1", "feat: one"), commit("b2", "fix: two")],
      }),
    ).toEqual([]);
  });

  it("accepts an empty or missing body", () => {
    expect(checkPullRequest({ author: "x", body: null, commits: [commit("a1", "feat: one")] })).toEqual([]);
  });

  it("accepts a release-please pull request", () => {
    expect(
      checkPullRequest({
        author: "github-actions[bot]",
        body: ":robot: I have created a release\n\nThis PR was generated with [Release Please](https://github.com/googleapis/release-please).",
        commits: [commit("a1", "chore(main): release wepwawet 0.9.0")],
      }),
    ).toEqual([]);
  });

  it("rejects attribution in the body", () => {
    const errors = checkPullRequest({
      author: "x",
      body: "Done.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)",
      commits: [commit("a1", "feat: one")],
    });
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain("PR body");
  });

  it("reports every bad commit with its short sha", () => {
    const errors = checkPullRequest({
      author: "x",
      body: "",
      commits: [
        commit("aaaaaaaaaaaa", "bad subject"),
        commit("bbbbbbbbbbbb", "feat: ok"),
        commit("cccccccccccc", "nope"),
      ],
    });
    expect(errors).toHaveLength(2);
    expect(errors[0]).toContain("aaaaaaa");
    expect(errors[1]).toContain("ccccccc");
  });

  it("limits kheprilab-agent[bot] to exactly one commit", () => {
    const bot = "kheprilab-agent[bot]";
    expect(checkPullRequest({ author: bot, body: "", commits: [commit("a1", "feat: one")] })).toEqual([]);
    const errors = checkPullRequest({
      author: bot,
      body: "",
      commits: [commit("a1", "feat: one"), commit("b2", "fix: two")],
    });
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain("exactly one commit");
    expect(checkPullRequest({ author: bot, body: "", commits: [] })).toHaveLength(1);
  });
});
